# Setup git pre-commit hook for ticket-api
$hookDir = Join-Path $PSScriptRoot "..\\.git\\hooks"
$preCommitPath = Join-Path $hookDir "pre-commit"

if (-not (Test-Path $hookDir)) {
    Write-Error "Git hooks directory not found at $hookDir"
    exit 1
}

$hookContent = @'
#!/bin/sh
# Auto-generated by scripts/setup-git-hooks.ps1
echo "Executing pre-commit verification gate..."
if command -v powershell >/dev/null 2>&1; then
    powershell -ExecutionPolicy Bypass -File scripts/verify-all.ps1
elif command -v pwsh >/dev/null 2>&1; then
    pwsh -ExecutionPolicy Bypass -File scripts/verify-all.ps1
elif [ -f "scripts/verify-all.sh" ]; then
    bash scripts/verify-all.sh
else
    echo "Warning: No verification script runner found."
    exit 1
fi
exit $?
'@

[System.IO.File]::WriteAllText($preCommitPath, $hookContent, [System.Text.Encoding]::ASCII)
Write-Host "Git pre-commit hook successfully installed at: $preCommitPath" -ForegroundColor Green
